        KosButton {
            Layout.fillWidth: true
            text: root.cancelLabel
            secondary: true
            onClicked: root.reject()
        }

        KosButton {
            Layout.fillWidth: true
            text: qsTr("Delete event")
            visible: root.editing
            destructive: true
            secondary: true
            onClicked: {
                root.deleteRequested(root.editingId)
                root.close()
            }
        }
    }
}

